'use strict';
(function(root){let atlas;function load(){if(!atlas){atlas=new Image;atlas.src='rpg-fx/mage/mage-atlas.png';}return atlas;}
function art(p,row,x,y,t,w=100,h=w,angle=0,duration=.75,alpha=1){if(t<0||t>=duration)return;const im=load();if(!im.complete||!im.naturalWidth)return;p.save();p.imageSmoothingEnabled=false;p.globalAlpha*=alpha*Math.min(1,(duration-t)*12);p.translate(x,y);p.rotate(angle);p.drawImage(im,Math.min(3,Math.floor(t/duration*4))*256,row*256,256,256,-w/2,-h/2,w,h);p.restore();}
let projectileAtlas;function rayArt(p,row,x,y,t,w,h,angle=0,duration=.6){if(t<0||t>=duration)return;if(!projectileAtlas){projectileAtlas=new Image;projectileAtlas.src='rpg-fx/mage/projectile-atlas.png';}if(!projectileAtlas.complete||!projectileAtlas.naturalWidth)return;p.save();p.imageSmoothingEnabled=false;p.globalAlpha*=Math.min(1,(duration-t)*10);p.translate(x,y);p.rotate(angle);p.drawImage(projectileAtlas,Math.min(3,Math.floor(t/duration*4))*256,row*256+64,256,128,-w/2,-h/2,w,h);p.restore();}
const rowFor=cell=>[0,1,2,3,4,5,6][cell]||0;function diamond(p,x,y,size,color){p.fillStyle=color;p.beginPath();p.moveTo(x,y-size);p.lineTo(x+size*.7,y);p.lineTo(x,y+size);p.lineTo(x-size*.7,y);p.closePath();p.fill();}
function lightning(p,from,to,t,alpha=1){if(t>.45||t<0)return;p.save();p.globalAlpha*=alpha*(1-t/.45);p.lineWidth=4;p.strokeStyle='#79b9ff';p.beginPath();p.moveTo(from.x,from.y-22);for(let i=1;i<8;i++){const q=i/8;p.lineTo(from.x+(to.x-from.x)*q+(i%2?-9:9),from.y-22+(to.y-from.y)*q);}p.lineTo(to.x,to.y-22);p.stroke();p.lineWidth=1.5;p.strokeStyle='#f3ffff';p.stroke();const length=Math.hypot(to.x-from.x,to.y-from.y);rayArt(p,3,(from.x+to.x)/2,(from.y+to.y)/2-22,t,length,45,Math.atan2(to.y-from.y,to.x-from.x),.45);p.restore();}
function draw(p,f,t,D){if(f.heroId!==2)return false;if(t<0||t>2)return true;const s=D?.skills.find(d=>d.heroId===2&&d.cell===f.cell&&d.slot===f.slot),kind=s?.actions[0]?.kind,o=f.from||f,row=rowFor(f.cell),r=f.radius||60,a=Math.atan2(f.y-o.y,f.x-o.x);
if(f.phase){const k=f.mageKind;if(['ice-lance','blood-lance','lightning-ray'].includes(k)){const length=f.length||0;if(length<1)return true;p.save();p.translate(o.x,o.y-22);p.rotate(a);p.beginPath();p.rect(0,-f.width*.9,length,f.width*1.8);p.clip();if(k==='lightning-ray')lightning(p,{x:0,y:22},{x:length,y:22},t);else rayArt(p,k==='ice-lance'?1:2,length/2,0,t,length,f.width*1.5,0,.55);p.restore();for(const target of f.targets||[])art(p,row,target.x,target.y-23,t,65,80,0,.55);return true;}
if(k==='lightning'){lightning(p,{x:f.x-10,y:f.y-160},f,t);if(o.x!==f.x)lightning(p,o,f,t,.7);art(p,1,f.x,f.y-22,t,75,100,0,.55);return true;}
if(k==='curse-link'){lightning(p,o,f,t,.4);art(p,5,f.x,f.y-35,t,50,55,0,.6);return true;}
if(k==='fire-brand'||k==='fire-impact'){root.RPG_SKILL_FX?.sheet(p,'blast',t,.65,f.x,f.y-20,k==='fire-brand'?100:70,90);return true;}if(k==='recover'||k==='blood-return'){for(let i=0;i<4;i++){const q=Math.min(1,t/.7),ang=i*Math.PI/2;art(p,k==='blood-return'?6:2,f.x+Math.cos(ang)*50*(1-q),f.y-28+Math.sin(ang)*32*(1-q),t,35,40,0,.8);}return true;}
if(k==='siphon'||k==='curse-harvest'){const q=Math.min(1,t/.7);art(p,row,f.x+(o.x-f.x)*q,f.y-25+(o.y-f.y)*q,t,k==='curse-harvest'?110:75,80,0,.8);return true;}
if(k==='meteor'||k==='tri-meteor'){art(p,k==='tri-meteor'?3:1,f.x,f.y-20,t,r*2,r*1.6,0,.9);return true;}
if(k==='frost-tick'){art(p,4,f.x,f.y-8,t,r*1.7,r*1.7,0,.65,.5);return true;}
if(k==='freeze'){art(p,4,f.x,f.y-27,t,70,95,0,.65);return true;}
if(['absolute-freeze','absolute-shatter','ice-shatter','frost-wave','frost-ring','ice-shift'].includes(k)){art(p,4,f.x,f.y-10,t,r*2,r*2,0,k==='absolute-freeze'?.5:.9);return true;}
if(k==='crimson-heart'){art(p,6,f.x,f.y-28,t,r*1.6,r*1.6,0,.38);return true;}
art(p,row,f.x,f.y-24,t,r*2,r*1.7,0,k==='calamity-seal'?.4:.8);return true;}
if(!kind)return true;const delayed={meteor:1,'tri-meteor':1.2,'absolute-zero':.8,calamity:.65,'curse-flood':.5,'frost-wave':.25,'frost-ring':.3,'ice-shift':.25};
if(delayed[kind]&&t<delayed[kind]){const d=delayed[kind],q=t/d;if(kind==='meteor'||kind==='tri-meteor'){art(p,kind==='meteor'?1:3,f.x-(1-q)*60,f.y-25-(1-q)*230,t,45+q*40,65+q*50,.3,d);return true;}art(p,row,f.x,f.y-10,t,kind==='absolute-zero'?150:90,90,0,d,.45);return true;}
if(['efficiency','contract'].includes(kind)){for(let i=0;i<4;i++){const a=i*Math.PI/2+t*2;diamond(p,o.x+Math.cos(a)*25,o.y-28+Math.sin(a)*20,4,kind==='contract'?'#b978ed':'#a9b7ff');}art(p,row,o.x,o.y-25,t,75,85,0,.9,.7);return true;}
if(['blood-gem','crimson-heart'].includes(kind))art(p,6,o.x,o.y-28,t,65,75,0,.4);else if(kind==='ignite')rayArt(p,0,o.x+16,o.y-25,t,40,25,0,.3);else if(['arcane-bolt','curse-bolt'].includes(kind))art(p,row,o.x+16,o.y-25,t,40,45,0,.3);else if(!delayed[kind])art(p,row,o.x,o.y-27,t,55,65,0,.35);return true;}
function ground(p,g,time){if(g.s.active!==2||!g.c?.mage)return;for(const z of g.c.mage.zones){p.save();p.beginPath();p.arc(z.x,z.y,z.radius,0,Math.PI*2);p.clip();art(p,4,z.x,z.y,time%1.7,z.radius*2,z.radius*2,0,1.7,.65);p.restore();}}
function state(p,g,time){if(g.s.active!==2||!g.c?.mage)return;const b=g.c.mage;for(const q of b.shots){const row=q.kind==='fire'?1:q.kind==='curse'?2:q.kind==='blood'?6:0;if(q.kind==='fire')rayArt(p,0,q.x,q.y,time%.5,62,27,Math.atan2(q.dy,q.dx),.5);else if(q.kind==='blood')rayArt(p,2,q.x,q.y,time%.5,55,20,Math.atan2(q.dy,q.dx),.5);else art(p,row,q.x,q.y,time%.5,38,38,Math.atan2(q.dy,q.dx),.5);}
for(const e of g.c.enemies.filter(e=>e.hp>0)){const curse=e.mage?.curse,chill=e.mage?.chill;if(curse){art(p,g.h.cell===5?5:2,e.x,e.y-62,time%1.2,34,36,0,1.2,.8);for(let i=0;i<curse.stacks;i++)diamond(p,e.x-12+i*6,e.y-78,2.5,'#cf8ef2');}if(chill)for(let i=0;i<chill.stacks;i++)diamond(p,e.x-12+i*6,e.y-52,3,'#b8efff');if(e.mage?.fire)art(p,1,e.x,e.y-18,time%1.1,35,45,0,1.1,.65);}
for(let i=0;i<b.elements.length;i++){const a=time+i*Math.PI*2/Math.max(1,b.elements.length),colors={fire:'#ff965d',ice:'#b6edff',lightning:'#ffe393'};diamond(p,g.c.x+Math.cos(a)*25,g.c.y-38+Math.sin(a)*13,5,colors[b.elements[i]]);}for(let i=0;i<(g.h.cell===6?b.blood:0);i++)diamond(p,g.c.x-21+i*6,g.c.y-67,3.5,'#f96a83');}
root.RPG_MAGE_FX={draw,state,ground};})(typeof window!=='undefined'?window:globalThis);
